var player = GetPlayer();

// Получаем значения переменных Time_1 и Time_Basic_1
var time1 = player.GetVar("Time_1"); // формат ММ:СС
var timeBasic1 = player.GetVar("Time_Basic_1"); // формат ММ:СС

// Функция для преобразования времени в формате ММ:СС в минуты
function convertToMinutes(timeStr) {
  var parts = timeStr.split(":");
  var minutes = parseInt(parts[0], 10); // получаем минуты
  return minutes;
}

// Преобразуем значения переменных в минуты
var minutes1 = convertToMinutes(time1);
var minutesBasic1 = convertToMinutes(timeBasic1);

// Вычисляем разницу в минутах
var minutesSpent = minutesBasic1 - minutes1;

// Обновляем значение переменной Time_Remain_1
player.SetVar("Time_Remain_1", minutesSpent);

var player = GetPlayer();

// Получаем текущую дату и время
var currentDate = new Date();

// Преобразуем текущую дату в формат ДД.ММ.ГГГГ
var day = currentDate.getDate();
var month = currentDate.getMonth() + 1; // Месяцы в JavaScript начинаются с 0
var year = currentDate.getFullYear();

// Форматируем день и месяц с ведущим нулем
day = day < 10 ? '0' + day : day;
month = month < 10 ? '0' + month : month;

// Создаем строку в формате ДД.ММ.ГГГГ
var formattedDateFinished = day + "." + month + "." + year;

// Устанавливаем значение переменной DateFinished
player.SetVar("DateFinished", formattedDateFinished);

// Добавляем 14 дней к текущему времени
var futureDate = new Date(currentDate.getTime() + 14 * 24 * 60 * 60 * 1000);

// Преобразуем дату в формат ДД:ММ:ГГГГ
day = futureDate.getDate();
month = futureDate.getMonth() + 1;
year = futureDate.getFullYear();

// Форматируем день и месяц с ведущим нулем
day = day < 10 ? '0' + day : day;
month = month < 10 ? '0' + month : month;

// Преобразуем время в формат ЧЧ:ММ:СС
var hours = futureDate.getHours();
var minutes = futureDate.getMinutes();
var seconds = futureDate.getSeconds();

// Форматируем часы, минуты и секунды с ведущим нулем
hours = hours < 10 ? '0' + hours : hours;
minutes = minutes < 10 ? '0' + minutes : minutes;
seconds = seconds < 10 ? '0' + seconds : seconds;

// Создаем строку в формате ДД:ММ:ГГГГ ЧЧ:ММ:СС
var formattedDateUnblock = day + ":" + month + ":" + year + " " + hours + ":" + minutes + ":" + seconds;

// Устанавливаем значение переменной Date_Unblock
player.SetVar("Date_Unblock", formattedDateUnblock);

var player = GetPlayer();

// Получаем значения переменных из Storyline
var dateEnd = player.GetVar("Date_End");  // Например: "30.08.2024" или "30:08:2024"
var timeEnd = player.GetVar("Time_End");  // Например: "10:26:25"
var dateUnblock = player.GetVar("Date_Unblock");  // Например: "13.09.2024 10:26:25" или "13:09:2024 10.26.25"

// Функция для преобразования строки даты и времени в объект Date
function parseDateTime(dateStr, timeStr) {
    // Заменяем любые двоеточия на точки в строке даты
    dateStr = dateStr.replace(/:/g, '.');
    
    // Заменяем любые точки на двоеточия в строке времени
    if (timeStr) {
        timeStr = timeStr.replace(/\./g, ':');
    } else {
        timeStr = "00:00:00"; // Если время не указано, устанавливаем 00:00:00
    }
    
    var partsDate = dateStr.split('.');
    var partsTime = timeStr.split(':');
    
    return new Date(partsDate[2], partsDate[1] - 1, partsDate[0], partsTime[0], partsTime[1], partsTime[2]);
}

// Преобразуем строки в объекты Date
var currentDateTime = new Date();
var dateEndObj = parseDateTime(dateEnd, timeEnd);
var dateUnblockObj = parseDateTime(dateUnblock.split(' ')[0], dateUnblock.split(' ')[1]);

// Логи текущей даты и времени
console.log("Текущая дата и время: " + currentDateTime.toString());
console.log("Date_End и Time_End как объект Date: " + dateEndObj.toString());
console.log("Date_Unblock как объект Date: " + dateUnblockObj.toString());

// Логика проверки условий
if (currentDateTime > dateEndObj) {
    player.SetVar("FinalView", 100);
    console.log("Условие выполнено: текущая дата и время больше, чем Date_End и Time_End. FinalView установлен на 100.");
} else {
    console.log("Условие не выполнено: текущая дата и время не больше, чем Date_End и Time_End.");
}

if (currentDateTime > dateUnblockObj) {
    player.SetVar("FinalView", 200);
    console.log("Условие выполнено: текущая дата и время больше, чем Date_Unblock. FinalView установлен на 200.");
} else {
    console.log("Условие не выполнено: текущая дата и время не больше, чем Date_Unblock.");
}
